/**
 * RFC 9457 Problem Details for HTTP APIs
 * Matches the format produced by Spring Boot 4 / GlobalExceptionHandler.
 */
export interface ProblemDetail {
  /** A URI reference that identifies the problem type. */
  type?: string;
  /** A short, human-readable summary of the problem type. */
  title: string;
  /** The HTTP status code generated by the origin server. */
  status: number;
  /** A human-readable explanation specific to this occurrence of the problem. */
  detail?: string;
  /** A URI reference that identifies the specific occurrence of the problem. */
  instance?: string;
  /** Field-level validation errors (extension used by Validation Failed 400). */
  errors?: string[];
  /** Dynamic extension members */
  [key: string]: unknown;
}

/**
 * Type guard to check if an arbitrary object is a RFC 9457 ProblemDetail.
 */
export function isProblemDetail(value: unknown): value is ProblemDetail {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.status === 'number' &&
    typeof candidate.title === 'string'
  );
}

